/**
 * What the UI asks for
 */

public enum AppAction: Equatable, Hashable {
    
    /**
     * Pair with the invite in scanned text: a `cmcp2…` ticket alone, or
     * the install command `companion invite` prints
     */
    case pair(
        /**
         * What the camera read
         */scanned: String
    )
    /**
     * Open the read's value with Face ID and send it
     */
    case approve(
        /**
         * The read
         */id: String
    )
    /**
     * Refuse the read
     */
    case deny(
        /**
         * The read
         */id: String
    )
    /**
     * Remove a finished read from the list
     */
    case dismiss(
        /**
         * The read
         */id: String
    )
    /**
     * Tell the gateway to forget this phone, then drop its keys
     */
    case unpair
    /**
     * The app came to the foreground: connect
     */
    case foreground
    /**
     * The app went to the background: hang up before iOS suspends it
     */
    case background
    /**
     * The app was opened from a push for this read
     */
    case openedFromPush(
        /**
         * The request id in the push
         */id: String, 
        /**
         * The reference in the push
         */reference: String, 
        /**
         * The gateway name in the push
         */gateway: String
    )
    /**
     * APNs gave this token, or `None` when notifications are off
     */
    case pushToken(
        /**
         * The device token as lowercase hex
         */token: String?, 
        /**
         * Which environment issued it
         */environment: PushEnvironment
    )





}

#if compiler(>=6)
extension AppAction: Sendable {}
#endif

#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public struct FfiConverterTypeAppAction: FfiConverterRustBuffer {
    typealias SwiftType = AppAction

    public static func read(from buf: inout (data: Data, offset: Data.Index)) throws -> AppAction {
        let variant: Int32 = try readInt(&buf)
        switch variant {
        
        case 1: return .pair(scanned: try FfiConverterString.read(from: &buf)
        )
        
        case 2: return .approve(id: try FfiConverterString.read(from: &buf)
        )
        
        case 3: return .deny(id: try FfiConverterString.read(from: &buf)
        )
        
        case 4: return .dismiss(id: try FfiConverterString.read(from: &buf)
        )
        
        case 5: return .unpair
        
        case 6: return .foreground
        
        case 7: return .background
        
        case 8: return .openedFromPush(id: try FfiConverterString.read(from: &buf), reference: try FfiConverterString.read(from: &buf), gateway: try FfiConverterString.read(from: &buf)
        )
        
        case 9: return .pushToken(token: try FfiConverterOptionString.read(from: &buf), environment: try FfiConverterTypePushEnvironment.read(from: &buf)
        )
        
        default: throw UniffiInternalError.unexpectedEnumCase
        }
    }

    public static func write(_ value: AppAction, into buf: inout [UInt8]) {
        switch value {
        
        
        case let .pair(scanned):
            writeInt(&buf, Int32(1))
            FfiConverterString.write(scanned, into: &buf)
            
        
        case let .approve(id):
            writeInt(&buf, Int32(2))
            FfiConverterString.write(id, into: &buf)
            
        
        case let .deny(id):
            writeInt(&buf, Int32(3))
            FfiConverterString.write(id, into: &buf)
            
        
        case let .dismiss(id):
            writeInt(&buf, Int32(4))
            FfiConverterString.write(id, into: &buf)
            
        
        case .unpair:
            writeInt(&buf, Int32(5))
        
        
        case .foreground:
            writeInt(&buf, Int32(6))
        
        
        case .background:
            writeInt(&buf, Int32(7))
        
        
        case let .openedFromPush(id,reference,gateway):
            writeInt(&buf, Int32(8))
            FfiConverterString.write(id, into: &buf)
            FfiConverterString.write(reference, into: &buf)
            FfiConverterString.write(gateway, into: &buf)
            
        
        case let .pushToken(token,environment):
            writeInt(&buf, Int32(9))
            FfiConverterOptionString.write(token, into: &buf)
            FfiConverterTypePushEnvironment.write(environment, into: &buf)
            
        }
    }
}


