     */
    case waiting
    /**
     * Face ID is up
     */
    case approving
    /**
     * The value was sent
     */
    case approved
    /**
     * The owner refused
     */
    case denied
    /**
     * The gateway gave up waiting
     */
    case expired
    /**
     * Another source answered first, so the gateway no longer wants it
     */
    case withdrawn
    /**
     * The reference is not on this phone's allow list, so it was refused
     * without asking
     */
    case notAllowed
    /**
     * Opening the value failed
     */
    case failed(
        /**
         * Why
         */message: String
    )





}

