/**
 * One change to [`AppState`], sent to the [`Reconciler`]
 */

public enum Update: Equatable, Hashable {
    
    /**
     * The paired gateway changed
     */
    case gateway(GatewayInfo?
    )
    /**
     * The link changed
     */
    case connection(ConnectionState
    )
    /**
     * The reads changed
     */
    case reads([PendingRead]
    )
    /**
     * The pairing moved on
     */
    case pairing(PairingState
    )





}

